import{_ as o,o as i,c as l,a as t}from"./app.DLPSkIGI.js";const p=JSON.parse('{"title":"Hook Spiral Guard","description":"","frontmatter":{},"headers":[],"relativePath":"reference/HOOK_SPIRAL_GUARD.md","filePath":"reference/HOOK_SPIRAL_GUARD.md","lastUpdated":1771835514000}'),a={name:"reference/HOOK_SPIRAL_GUARD.md"};function c(d,e,r,s,n,u){return i(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="hook-spiral-guard" tabindex="-1">Hook Spiral Guard <a class="header-anchor" href="#hook-spiral-guard" aria-label="Permalink to &quot;Hook Spiral Guard&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>The regression spiral guard prevents agent sessions from accumulating hidden failures until quality collapses.</p><p>It enforces:</p><ul><li>continuous regression detection,</li><li>interrupt-style escalation for critical growth,</li><li>test/build/environment-first workflow,</li><li>e2e-first evidence requirements for no-human-feedback development loops,</li><li>freshness thresholds on test/build/e2e evidence artifacts,</li><li>deterministic per-band retry budgets and cooldown windows with explicit remediation directives.</li></ul><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><ul><li><code>hooks/governance-gates.sh</code><ul><li>Gate: <code>regression-spiral-guard</code></li><li>Selector mode: <ul><li><code>QA_GATES_ONLY</code> / <code>THEGENT_GATES_ONLY</code> enable selected-gate execution</li><li>selectors are canonicalized (trim, drop empty, dedupe, sort) before execution/cache scope</li></ul></li><li>Writes: <ul><li><code>.claude/verification/regression-spiral-guard.json</code></li><li><code>.claude/verification/regression-spiral-state.json</code></li><li><code>.claude/verification/regression-spiral-alert.json</code></li><li><code>.claude/verification/regression-spiral-metrics.jsonl</code></li></ul></li></ul></li><li><code>hooks/continuous-work-guard.sh</code><ul><li>Reads <code>regression-spiral-alert.json</code></li><li>Emits interrupt instructions and exits <code>2</code> only for <code>severity=critical</code></li></ul></li><li><code>hooks/lib/spiral-config.sh</code><ul><li>Shared loader that consumes Rust <code>hook-dispatcher governance spiral-config</code></li></ul></li><li><code>hooks/hook-dispatcher/src/main.rs</code><ul><li>Subcommand: <code>governance spiral-config [path] [--format env|json]</code></li><li>Subcommand: <code>governance spiral-trend [path] [--window N]</code></li><li>Central parser authority for spiral policy defaults + YAML overrides</li><li>Trend aggregation over metrics stream (breach rate, interrupt count, max streak, MTTR proxy, stale evidence event counts)</li></ul></li></ul><h2 id="config-resolution-order" tabindex="-1">Config Resolution Order <a class="header-anchor" href="#config-resolution-order" aria-label="Permalink to &quot;Config Resolution Order&quot;">​</a></h2><ol><li>Environment variables (<code>QA_SPIRAL_*</code>, <code>QA_REQUIRE_*</code>)</li><li><code>hooks/hook-config.yaml</code> at <code>settings.regression_spiral_guard</code></li><li>Built-in defaults in <code>hooks/lib/spiral-config.sh</code></li></ol><h2 id="selector-canonicalization-contract" tabindex="-1">Selector Canonicalization Contract <a class="header-anchor" href="#selector-canonicalization-contract" aria-label="Permalink to &quot;Selector Canonicalization Contract&quot;">​</a></h2><ul><li>Input sources: <code>QA_GATES_ONLY</code> (preferred), fallback <code>THEGENT_GATES_ONLY</code></li><li>Canonicalization pipeline in <code>hooks/governance-gates.sh</code>: <ul><li>remove whitespace</li><li>split CSV</li><li>drop empty entries</li><li>dedupe entries</li><li>stable sort (<code>LC_ALL=C sort -u</code>)</li><li>rejoin CSV</li></ul></li><li>Canonical selector value is used for: <ul><li>selected-mode execution list</li><li>cache key scope (<code>GOVERNANCE-GATES:&lt;canonical-selector&gt;</code>)</li></ul></li><li>Empty selector behavior: <ul><li>If selector env is explicitly provided but canonical list is empty, selector mode still activates and fails closed with explicit reason (<code>no valid gate labels ...</code>).</li></ul></li></ul><h3 id="selector-examples" tabindex="-1">Selector Examples <a class="header-anchor" href="#selector-examples" aria-label="Permalink to &quot;Selector Examples&quot;">​</a></h3><ul><li>Single gate: <ul><li><code>QA_GATES_ONLY=regression_spiral_guard hooks/governance-gates.sh</code></li></ul></li><li>Multi gate (canonicalized for execution + cache scope): <ul><li>input: <code>QA_GATES_ONLY=&quot;reliability, regression_spiral_guard, reliability&quot;</code></li><li>canonical selector: <code>regression_spiral_guard,reliability</code></li></ul></li><li>Empty entries fail closed: <ul><li><code>QA_GATES_ONLY=&quot; , , &quot; hooks/governance-gates.sh</code></li><li>expected: fail-closed with <code>no valid gate labels in QA_GATES_ONLY=,,</code></li></ul></li><li>Malformed/unknown token fail closed: <ul><li><code>QA_GATES_ONLY=&quot;regression_spiral_guard;rm-rf/&quot; hooks/governance-gates.sh</code></li><li>expected: fail-closed with <code>unknown gate label: ...</code></li></ul></li></ul><h2 id="supported-environment-overrides" tabindex="-1">Supported Environment Overrides <a class="header-anchor" href="#supported-environment-overrides" aria-label="Permalink to &quot;Supported Environment Overrides&quot;">​</a></h2><ul><li><code>QA_SPIRAL_MAX_FAILED_TESTS</code></li><li><code>QA_SPIRAL_MAX_FLAKY_TESTS</code></li><li><code>QA_SPIRAL_MAX_MISSING_TEST_PAIRS</code></li><li><code>QA_SPIRAL_MAX_MISSING_TEST_TYPES</code></li><li><code>QA_SPIRAL_MAX_TEST_EVIDENCE_AGE_MINUTES</code></li><li><code>QA_SPIRAL_MAX_BUILD_EVIDENCE_AGE_MINUTES</code></li><li><code>QA_SPIRAL_MAX_E2E_EVIDENCE_AGE_MINUTES</code></li><li><code>QA_SPIRAL_STREAK_TRIGGER</code></li><li><code>QA_REQUIRE_E2E_FIRST</code></li><li><code>QA_REQUIRE_ENV_READY_FIRST</code></li><li><code>QA_SPIRAL_MAX_YELLOW_RETRIES</code></li><li><code>QA_SPIRAL_MAX_RED_RETRIES</code></li><li><code>QA_SPIRAL_YELLOW_COOLDOWN_MINUTES</code></li><li><code>QA_SPIRAL_RED_COOLDOWN_MINUTES</code></li><li><code>QA_SPIRAL_DIRECTIVE_GREEN</code></li><li><code>QA_SPIRAL_DIRECTIVE_YELLOW</code></li><li><code>QA_SPIRAL_DIRECTIVE_RED</code></li><li><code>QA_REGRESSION_SPIRAL_FAIL_CLOSED</code></li></ul><h2 id="freshness-threshold-defaults" tabindex="-1">Freshness Threshold Defaults <a class="header-anchor" href="#freshness-threshold-defaults" aria-label="Permalink to &quot;Freshness Threshold Defaults&quot;">​</a></h2><p>From <code>hooks/hook-config.yaml</code> (<code>settings.regression_spiral_guard</code>):</p><ul><li><code>max_test_evidence_age_minutes: 90</code> for async test evidence (<code>RESULTS_FILE</code>)</li><li><code>max_build_evidence_age_minutes: 90</code> for build/env evidence (<code>.claude/verification/qa-state.json</code>)</li><li><code>max_e2e_evidence_age_minutes: 180</code> for e2e evidence (<code>.claude/verification/qa-attestation.json</code>, when <code>require_e2e_first=true</code>)</li></ul><p>Missing files count as stale evidence violations.</p><h2 id="trend-output-fields" tabindex="-1">Trend Output Fields <a class="header-anchor" href="#trend-output-fields" aria-label="Permalink to &quot;Trend Output Fields&quot;">​</a></h2><p><code>hook-dispatcher governance spiral-trend</code> now includes:</p><ul><li><code>stale_test_evidence_events</code></li><li><code>stale_build_evidence_events</code></li><li><code>stale_e2e_evidence_events</code></li><li><code>pressure_score</code></li><li><code>policy_band</code> (<code>green</code>, <code>yellow</code>, <code>red</code>)</li></ul><p>Pressure score is deterministic and normalized to <code>[0,1]</code>:</p><ul><li><code>0.40 * breach_rate</code></li><li><code>0.20 * interrupt_rate</code></li><li><code>0.20 * stale_evidence_rate</code></li><li><code>0.15 * streak_pressure</code> (<code>max_streak/3</code>, capped at <code>1</code>)</li><li><code>0.05 * positive_violations_delta_pressure</code> (<code>max(violations_delta,0)/3</code>, capped at <code>1</code>)</li></ul><p>Policy bands:</p><ul><li><code>red</code> when <code>pressure_score &gt;= 0.75</code></li><li><code>yellow</code> when <code>pressure_score &gt;= 0.45</code> and <code>&lt; 0.75</code></li><li><code>green</code> otherwise</li></ul><p>Shell gate parity:</p><ul><li><code>hooks/governance-gates.sh</code> writes <code>pressure_score</code> and <code>policy_band</code> to both: <ul><li><code>.claude/verification/regression-spiral-guard.json</code></li><li><code>.claude/verification/regression-spiral-metrics.jsonl</code></li></ul></li><li><code>policy_band=red</code> is a strict hard-interrupt contract in shell gate logic: <ul><li><code>interrupt=true</code></li><li><code>enforcement_path=fail_closed</code></li></ul></li></ul><h2 id="spiral-band-ops-fields" tabindex="-1">Spiral Band Ops Fields <a class="header-anchor" href="#spiral-band-ops-fields" aria-label="Permalink to &quot;Spiral Band Ops Fields&quot;">​</a></h2><p>The spiral state/report/alert/metrics now share deterministic operational fields:</p><ul><li>State (<code>.claude/verification/regression-spiral-state.json</code>) <ul><li><code>band_retry_counts.green</code></li><li><code>band_retry_counts.yellow</code></li><li><code>band_retry_counts.red</code></li><li><code>cooldown_until</code> (epoch seconds, nullable)</li><li><code>escalation_stage</code></li><li><code>last_policy_band</code></li><li><code>last_directive</code></li></ul></li><li>Report (<code>.claude/verification/regression-spiral-guard.json</code>) <ul><li><code>remediation_directive</code></li><li><code>band_retry_count</code></li><li><code>cooldown_until</code></li><li><code>escalation_stage</code></li></ul></li><li>Alert (<code>.claude/verification/regression-spiral-alert.json</code>) <ul><li><code>policy_band</code></li><li><code>band_retry_count</code></li><li><code>cooldown_until</code></li><li><code>escalation_stage</code></li><li><code>remediation_directive</code></li></ul></li><li>Metrics JSONL (<code>.claude/verification/regression-spiral-metrics.jsonl</code>) <ul><li><code>remediation_directive</code></li><li><code>band_retry_count</code></li><li><code>cooldown_until</code></li><li><code>escalation_stage</code></li></ul></li></ul><h2 id="operational-lifecycle" tabindex="-1">Operational Lifecycle <a class="header-anchor" href="#operational-lifecycle" aria-label="Permalink to &quot;Operational Lifecycle&quot;">​</a></h2><ol><li>Spiral policy computes <code>pressure_score</code> and assigns a policy band (<code>green|yellow|red</code>).</li><li>Per-band retry counters are incremented deterministically and constrained by: <ul><li><code>max_yellow_retries</code></li><li><code>max_red_retries</code></li></ul></li><li>Cooldown windows are applied with: <ul><li><code>yellow_cooldown_minutes</code></li><li><code>red_cooldown_minutes</code></li></ul></li><li>If cooldown has elapsed, retry counters reset before evaluating the next event.</li><li>Repeated yellow events past threshold escalate deterministically into the red interrupt path.</li><li>Red remains a hard interrupt contract (<code>fail_closed</code>) and carries red remediation directive.</li><li><code>continuous-work-guard.sh</code> consumes alert fields and prints deterministic directive/cooldown context; it exits <code>2</code> only for <code>severity=critical</code>.</li></ol><h2 id="operational-notes" tabindex="-1">Operational Notes <a class="header-anchor" href="#operational-notes" aria-label="Permalink to &quot;Operational Notes&quot;">​</a></h2><ul><li>Warning alerts do not hard-stop work.</li><li>Critical alerts trigger interruption behavior.</li><li>Alerts are cleared automatically when spiral conditions recover.</li><li>Attempt counters are session-scoped to reduce cross-session false lockouts.</li></ul><h2 id="pre-work-hard-gate" tabindex="-1">Pre-Work Hard Gate <a class="header-anchor" href="#pre-work-hard-gate" aria-label="Permalink to &quot;Pre-Work Hard Gate&quot;">​</a></h2><ul><li>Task start surfaces enforce a pre-work hard gate before starting new work.</li><li>The gate blocks when required freshness evidence is missing or stale: <ul><li>test evidence: <code>~/.claude/.async-test-results.json</code></li><li>build/env evidence: <code>&lt;project&gt;/.claude/verification/qa-state.json</code></li><li>e2e evidence (when <code>require_e2e_first=true</code>): <code>&lt;project&gt;/.claude/verification/qa-attestation.json</code></li></ul></li><li>Thresholds are loaded from <code>hooks/hook-config.yaml</code> at <code>settings.regression_spiral_guard</code>, with defaults: <ul><li><code>require_e2e_first=true</code></li><li><code>max_test_evidence_age_minutes=90</code></li><li><code>max_build_evidence_age_minutes=90</code></li><li><code>max_e2e_evidence_age_minutes=180</code></li></ul></li></ul><h3 id="start-surface-parity-matrix" tabindex="-1">Start-Surface Parity Matrix <a class="header-anchor" href="#start-surface-parity-matrix" aria-label="Permalink to &quot;Start-Surface Parity Matrix&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Surface</th><th>Entry Point</th><th>Gate Behavior on Failure</th></tr></thead><tbody><tr><td>CLI</td><td><code>thegent plan next</code> (<code>do_next_impl</code>)</td><td>Returns <code>governance_blocked=true</code> payload, includes <code>governance_block.remediation_steps</code>, blocks start</td></tr><tr><td>CLI</td><td><code>thegent plan get-next</code> (<code>do_next_impl</code> wrapper)</td><td>Propagates <code>governance_blocked=true</code> with remediation and exits non-zero</td></tr><tr><td>CLI</td><td><code>thegent plan spawn-next</code> (<code>spawn_next_impl</code>)</td><td>Propagates <code>governance_blocked=true</code>; does not spawn or claim</td></tr><tr><td>CLI</td><td><code>thegent plan claim</code> (<code>work_stream_claim_impl</code>)</td><td>Returns <code>success=false</code> + <code>governance_blocked=true</code> with remediation</td></tr><tr><td>MCP</td><td><code>thegent_do_next</code></td><td>Returns blocked payload unchanged from <code>do_next_impl</code></td></tr><tr><td>MCP</td><td><code>thegent_plan_get_next</code></td><td>Returns error payload that preserves <code>governance_blocked</code> + remediation</td></tr><tr><td>Auto-launch</td><td><code>AutoLaunchSystem._try_launch_next</code> fallback via <code>do_next_impl</code></td><td>Records <code>governance_blocked</code> event and skips launch batch</td></tr><tr><td>Auto-launch</td><td><code>AutoLaunchSystem._launch_item</code> claim/start path</td><td>Uses <code>work_stream_claim_impl</code>; on block records <code>claim_failed</code> and skips <code>bg_impl</code> start</td></tr></tbody></table><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>Run:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:hooks:governance</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This runs:</p><ul><li>shell syntax checks for relevant hooks,</li><li>unit tests for YAML config loading and defaults,</li><li>trend command tests over spiral metrics stream,</li><li>selector-mode fast + strict lanes,</li><li>selector artifact schema checks and schema-drift sentinel checks.</li></ul><h2 id="ci-lane-mapping" tabindex="-1">CI Lane Mapping <a class="header-anchor" href="#ci-lane-mapping" aria-label="Permalink to &quot;CI Lane Mapping&quot;">​</a></h2><ul><li>PR / manual: <ul><li>GitHub Actions job: <code>governance-selector-fast</code></li><li>Task target: <code>task test:hooks:selector-fast</code></li></ul></li><li>Push / nightly / manual: <ul><li>GitHub Actions job: <code>governance-selector-strict</code></li><li>Task target: <code>task test:hooks:selector-strict</code></li></ul></li><li>Both lanes emit fail-closed evidence snippets (<code>fail-closed</code>, <code>policy_band=red</code>, <code>critical_interrupt</code>) on failure and upload logs as artifacts.</li></ul><h2 id="artifact-schema-contract" tabindex="-1">Artifact Schema Contract <a class="header-anchor" href="#artifact-schema-contract" aria-label="Permalink to &quot;Artifact Schema Contract&quot;">​</a></h2><ul><li>Selector-mode contracts are enforced by tests in <code>tests/test_hook_governance_gate_selector.py</code>: <ul><li>Required key/type assertions: <ul><li>report (<code>regression-spiral-guard.json</code>)</li><li>metrics line (<code>regression-spiral-metrics.jsonl</code>)</li><li>state (<code>regression-spiral-state.json</code>)</li><li>alert (<code>regression-spiral-alert.json</code>, when expected)</li></ul></li><li>Schema-drift sentinel: <ul><li>exact key-set assertions for report/metric/state/alert payloads to catch accidental contract drift.</li></ul></li><li>Contract version: <ul><li>all spiral artifacts emit <code>contract_version: &quot;v1&quot;</code> and tests enforce it.</li></ul></li></ul></li></ul>',48)])])}const h=o(a,[["render",c]]);export{p as __pageData,h as default};
